CREATE OR REPLACE FUNCTION public.guard_group_last_main_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.is_active and old.role='main_admin' and (TG_OP='DELETE' or not new.is_active or new.role<>'main_admin' or new.club_id is distinct from old.club_id) then
    if current_setting('transaction_isolation')<>'read committed' then raise exception '管理者の在籍変更はREAD COMMITTEDで実行してください'; end if;
    perform 1 from public.clubs where id=old.club_id for update;
    if (select count(*) from public.club_members where club_id=old.club_id and is_active and role='main_admin')<=1 then
      raise exception 'メイン管理者は最低1人必要です';
    end if;
  end if;
  if TG_OP='DELETE' then return old; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION profile_link_private.guard_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare column_name text; new_id uuid; old_id uuid; linked uuid; active boolean;
begin
  foreach column_name in array TG_ARGV loop
    new_id := (to_jsonb(new)->>column_name)::uuid;
    old_id := case when TG_OP = 'UPDATE' then (to_jsonb(old)->>column_name)::uuid end;
    if new_id is not null and (TG_OP = 'INSERT' or new_id is distinct from old_id) then
      select linked_auth_user_id,is_active into linked,active from public.player_profiles where id = new_id for share;
      if not found or not active then raise exception '無効化・統合済みの選手には新しい所属・参加・試合を追加できません'; end if;
      if current_setting('role') in ('anon','authenticated') and TG_TABLE_NAME in ('club_members','event_participants') and (to_jsonb(new)->>'profile_id') is not null
        and linked is distinct from (to_jsonb(new)->>'profile_id')::uuid then raise exception '旧profile_idと選手の連携アカウントが一致しません'; end if;
    end if;
  end loop;
  return new;
end $function$
